CREATE COLUMN TABLE "TEST_AP"."TPS1" ("TpsId" INTEGER CS_INT NOT NULL , "DispOrder" INTEGER CS_INT NOT NULL , "TpaId" INTEGER CS_INT NOT NULL , "Mandatory" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("TpsId", "TpaId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "TPS1_ORDER" ON "TEST_AP"."TPS1" ( "TpsId" ASC, "DispOrder" ASC )